import { TONE } from './messageToast';

// THE MESSAGE TONE ON THE WEB (fix round on feat/message-toast, 2026-10-02;
// FRONTEND_CONVENTIONS §26). Generated by the Web Audio API — no audio file,
// no install, no URL. The numbers are `TONE` in the mirrored
// realtime/messageToast.js, so the phone's WAV is the same sound.
//
// ONE AudioContext, created LAZILY on the first play and reused for every
// later one; `resume()` before each play (a context made outside a user
// gesture starts suspended). If the browser refuses — autoplay policy, no
// Web Audio at all, a constructor that throws — the tone is silent and
// nothing is thrown: the toast still shows.
//
// `getCtor` is injectable so ssr-message-toast can count constructions with a
// fake context; the default reads the browser's own.

export function defaultAudioContextCtor() {
  if (typeof window === 'undefined') return null;
  return window.AudioContext || window.webkitAudioContext || null;
}

// The sound itself on a running context: an 880 Hz sine whose gain rises to
// 0.3 over 10 ms, holds, and falls back to 0 over the last 10 ms of 150 ms.
function schedule(ctx) {
  const t0 = ctx.currentTime;
  const duration = TONE.durationMs / 1000;
  const fade = TONE.fadeMs / 1000;
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(TONE.freqHz, t0);
  gain.gain.setValueAtTime(0, t0);
  gain.gain.linearRampToValueAtTime(TONE.gain, t0 + fade);
  gain.gain.setValueAtTime(TONE.gain, t0 + duration - fade);
  gain.gain.linearRampToValueAtTime(0, t0 + duration);
  osc.connect(gain);
  gain.connect(ctx.destination);
  osc.start(t0);
  osc.stop(t0 + duration);
}

export function createTonePlayer(getCtor = defaultAudioContextCtor) {
  let ctx = null;

  // Returns true when a play was REQUESTED (the sound itself may still be
  // refused by the browser — silently), false when there is no audio at all.
  function play() {
    try {
      if (!ctx) {
        const Ctor = getCtor();
        if (!Ctor) return false;
        ctx = new Ctor();
      }
      const context = ctx;
      Promise.resolve(typeof context.resume === 'function' ? context.resume() : undefined)
        .then(() => {
          try {
            schedule(context);
          } catch {
            // A context that cannot make the sound stays silent.
          }
        })
        .catch(() => {
          // Autoplay policy refused resume(): silent, by design.
        });
      return true;
    } catch {
      return false;
    }
  }

  return { play };
}
